DECLARE @ITMNO VARCHAR(30) = '{2}' DECLARE @DOCNUM VARCHAR(30) = '{5}' DECLARE @ROUCOD VARCHAR(30) = '{5}' DECLARE @USER VARCHAR(30) = '#LOGIN_USER#'
IF NOT EXISTS ( SELECT TOP 1 * FROM QAINSPH WHERE DOCNUM = @DOCNUM ) BEGIN -- CREATE INSPH INSERT INTO QAINSPH ( DOCNUM , DOCDAT , ROUTYP , ITMNO , ROUCOD , CREUSR , CRETIM ) VALUES ( @DOCNUM , GETDATE() , 'IMI' , @ITMNO , @ROUCOD , @USER --CREUSR , GETDATE() --CRETIM ) -- CREATE INSPL INSERT INTO QAINSPL ( DOCNUM , OPENUM , OPESTD , OPEGRP , OPEUNT , CTLTYP , MEAFRQ , NMIN , NNOR , NMAX , TRXUSER , TRXDAT , CREUSR , CRETIM ) SELECT @DOCNUM , L.OPENUM , L.OPESTD , L.OPEGRP , L.OPEUNT , L.CTLTYP , L.MEAFRQ , L.VALMIN , L.VALNOR , L.VALMAX , @USER TRXUSER , GETDATE() TRXDAT , @USER CREUSR , GETDATE() CRETIM FROM QAROULIN L INNER JOIN QAROU R ON R.ROUCOD = L.ROUCOD WHERE R.ROUCOD = @ROUCOD;
-- 更新 Logic 的控制信息 UPDATE L SET L1CHECK = LC.L1CHECK , L2CHECK = LC.L2CHECK FROM QAINSPL L INNER JOIN ( SELECT T.OPENUM , MAX(IIF(T.VALLIN = 1 AND T.VALDES <> '', 1, 0)) L1CHECK , MAX(IIF(T.VALLIN = 2 AND T.VALDES <> '', 1, 0)) L2CHECK FROM QAROULINCTL T INNER JOIN QAROULIN L ON L.ROUCOD = T.ROUCOD AND L.OPENUM = T.OPENUM WHERE L.ROUCOD = @ROUCOD AND L.CTLTYP = 'L' AND T.VALTYP = 'L' GROUP BY T.OPENUM ) LC ON LC.OPENUM = L.OPENUM WHERE L.DOCNUM = @DOCNUM END
